// F28: per-test results from JUnit XML, with files that produced no testcases counted as load failures. The real
// sample below is generated by actually running bun's JUnit reporter over a file with a syntax error, because that
// is the exact shape the grader has to survive: bun drops such a file from the report entirely.
import { afterAll, describe, expect, test } from "bun:test";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { LOAD_ERROR_NAME, parseJunit } from "../src/grade/junit.ts";

const roots: string[] = [];
const tmpRoot = () => {
  const d = mkdtempSync(join(tmpdir(), "roster-junit-"));
  roots.push(d);
  return d;
};
afterAll(() => {
  for (const d of roots) rmSync(d, { recursive: true, force: true });
});

const suite = (file: string, body: string, name = "s") => `<testsuite name="${name}" file="${file}">${body}</testsuite>`;
const suites = (body: string) => `<?xml version="1.0" encoding="UTF-8"?><testsuites>${body}</testsuites>`;

describe("parseJunit: real bun report", () => {
  test("keeps per-test results and flags the file bun silently dropped", () => {
    const dir = tmpRoot();
    writeFileSync(
      join(dir, "calc.test.ts"),
      `import { expect, test } from "bun:test";\n` +
        `test("adds", () => { expect(1 + 1).toBe(2); });\n` +
        `test("subtracts", () => { expect(2 - 1).toBe(0); });\n` +
        `test.skip("later", () => {});\n`,
    );
    // A syntax error means the module never loads; bun's JUnit reporter emits no suite for it at all.
    writeFileSync(join(dir, "broken.test.ts"), `import { test } from "bun:test";\ntest("never", () => { let = ; });\n`);

    const out = join(dir, "junit.xml");
    Bun.spawnSync(["bun", "test", "--reporter=junit", `--reporter-outfile=${out}`], { cwd: dir });
    expect(existsSync(out)).toBe(true);
    const { tests, loadFailures } = parseJunit(readFileSync(out, "utf8"), ["calc.test.ts", "broken.test.ts"]);

    const calc = tests.filter((t) => t.file === "calc.test.ts");
    expect(calc.map((t) => [t.name, t.pass])).toEqual([
      ["adds", true],
      ["subtracts", false],
    ]); // the skipped case is not a result
    expect(loadFailures).toEqual(["broken.test.ts"]);
    expect(tests.filter((t) => t.file === "broken.test.ts")).toEqual([
      { file: "broken.test.ts", name: LOAD_ERROR_NAME, pass: false },
    ]);
  });
});

describe("parseJunit", () => {
  test("a testcase without a file attribute inherits the suite's", () => {
    const r = parseJunit(suites(suite("tests/calc.test.ts", `<testcase name="adds" file="tests/calc.test.ts"/>`)), [
      "tests/calc.test.ts",
    ]);
    expect(r).toEqual({ tests: [{ file: "tests/calc.test.ts", name: "adds", pass: true }], loadFailures: [] });
  });

  test("falls back to the suite name when no file attribute exists", () => {
    const r = parseJunit(suites(`<testsuite name="tests/calc.test.ts"><testcase name="adds"/></testsuite>`), [
      "tests/calc.test.ts",
    ]);
    expect(r.loadFailures).toEqual([]);
    expect(r.tests).toEqual([{ file: "tests/calc.test.ts", name: "adds", pass: true }]);
  });

  test("the testcase's own file wins over its suite's", () => {
    const xml = suites(
      `<testsuite name="group" file="tests/suite.test.ts"><testcase name="a" file="tests/other.test.ts"/></testsuite>`,
    );
    expect(parseJunit(xml, []).tests).toEqual([{ file: "tests/other.test.ts", name: "a", pass: true }]);
  });

  test("failure and error fail a case; skipped is excluded", () => {
    const xml = suites(
      suite(
        "tests/a.test.ts",
        `<testcase name="ok"/>` +
          `<testcase name="bad"><failure message="boom"/></testcase>` +
          `<testcase name="err"><error type="E"/></testcase>` +
          `<testcase name="skip"><skipped/></testcase>`,
      ),
    );
    expect(parseJunit(xml, ["tests/a.test.ts"]).tests).toEqual([
      { file: "tests/a.test.ts", name: "ok", pass: true },
      { file: "tests/a.test.ts", name: "bad", pass: false },
      { file: "tests/a.test.ts", name: "err", pass: false },
    ]);
  });

  test("a file whose cases all skipped still loaded, so it is not a load failure", () => {
    const xml = suites(suite("tests/a.test.ts", `<testcase name="skip"><skipped/></testcase>`));
    expect(parseJunit(xml, ["tests/a.test.ts"])).toEqual({ tests: [], loadFailures: [] });
  });

  test("every expected file with zero testcases gets one synthetic failing test", () => {
    const r = parseJunit(suites(suite("tests/a.test.ts", `<testcase name="ok"/>`)), [
      "tests/a.test.ts",
      "tests/gone.test.ts",
      "tests/never-ran.test.ts",
    ]);
    expect(r.loadFailures).toEqual(["tests/gone.test.ts", "tests/never-ran.test.ts"]);
    expect(r.tests).toEqual([
      { file: "tests/a.test.ts", name: "ok", pass: true },
      { file: "tests/gone.test.ts", name: "0 tests collected: load error", pass: false },
      { file: "tests/never-ran.test.ts", name: "0 tests collected: load error", pass: false },
    ]);
  });

  test("an empty report makes every expected file a load failure", () => {
    const r = parseJunit("", ["tests/a.test.ts", "tests/b.test.ts"]);
    expect(r.loadFailures).toEqual(["tests/a.test.ts", "tests/b.test.ts"]);
    expect(r.tests.every((t) => !t.pass && t.name === LOAD_ERROR_NAME)).toBe(true);
  });

  test("a leading ./ does not hide a file that ran", () => {
    const xml = suites(`<testsuite name="a" file="./tests/a.test.ts"><testcase name="ok"/></testsuite>`);
    const r = parseJunit(xml, ["tests/a.test.ts"]);
    expect(r.loadFailures).toEqual([]);
    expect(r.tests).toEqual([{ file: "tests/a.test.ts", name: "ok", pass: true }]);
  });

  test("attribute values are unescaped, single or double quoted", () => {
    const xml = suites(
      `<testsuite name="s" file='tests/a.test.ts'><testcase name="a &amp; b &quot;x&quot;"/></testsuite>`,
    );
    expect(parseJunit(xml, []).tests).toEqual([{ file: "tests/a.test.ts", name: `a & b "x"`, pass: true }]);
  });

  test("nested suites use the nearest enclosing file attribute", () => {
    const xml = suites(
      `<testsuite name="outer" file="tests/outer.test.ts">` +
        `<testsuite name="group"><testcase name="a"/></testsuite>` +
        `</testsuite>`,
    );
    expect(parseJunit(xml, ["tests/outer.test.ts"]).tests).toEqual([
      { file: "tests/outer.test.ts", name: "a", pass: true },
    ]);
  });

  test("an empty self-closing suite opens no scope", () => {
    const xml = suites(
      `<testsuite name="empty" file="tests/empty.test.ts"/>` +
        `<testsuite name="b" file="tests/b.test.ts"><testcase name="ok"/></testsuite>`,
    );
    expect(parseJunit(xml, ["tests/empty.test.ts", "tests/b.test.ts"]).loadFailures).toEqual(["tests/empty.test.ts"]);
  });

  test("results are returned for files that were not expected", () => {
    const xml = suites(
      suite("tests/a.test.ts", `<testcase name="a"/>`) + suite("tests/b.test.ts", `<testcase name="b"/>`),
    );
    const r = parseJunit(xml, ["tests/a.test.ts"]);
    expect(r.loadFailures).toEqual([]);
    expect(r.tests.map((t) => t.file)).toEqual(["tests/a.test.ts", "tests/b.test.ts"]);
  });

  test("a duplicate expected file is reported once", () => {
    const r = parseJunit("", ["tests/a.test.ts", "tests/a.test.ts"]);
    expect(r.loadFailures).toEqual(["tests/a.test.ts"]);
    expect(r.tests).toHaveLength(1);
  });
});

